import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const timelines = [];
  const resources = [];

  const colorMap = {
    background: 0x0b0b10,
    surface: 0x14141a,
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
  };

  // Load gear mesh
  const gearGlb = ctx.glbLoader.load('/prism-mock/orrery/meshes/gear-a.glb');

  // Create machined steel material
  const gearMaterial = new THREE.MeshPhysicalMaterial({
    color: 0xa0a0a0,
    roughness: 0.5,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
    anisotropy: 0.7,
  });
  resources.push(gearMaterial);

  // Primary gear
  const primaryGear = gearGlb.scene.clone();
  primaryGear.scale.set(1.6, 1.6, 1.6);
  primaryGear.position.set(0, 0, 0);
  primaryGear.traverse(node => {
    if (node instanceof THREE.Mesh) {
      node.material = gearMaterial;
    }
  });
  group.add(primaryGear);

  // Secondary gear
  const secondaryGear = gearGlb.scene.clone();
  secondaryGear.scale.set(0.9, 0.9, 0.9);
  secondaryGear.position.set(1.15, 0.35, -0.1);
  secondaryGear.traverse(node => {
    if (node instanceof THREE.Mesh) {
      node.material = gearMaterial;
    }
  });
  group.add(secondaryGear);

  // Jewel pivot sphere
  const jewelGeom = new THREE.SphereGeometry(0.12, 32, 32);
  const jewelMat = new THREE.MeshPhysicalMaterial({
    color: colorMap.accent,
    transmission: 0.6,
    ior: 1.76,
    emissive: colorMap.accent,
    emissiveIntensity: 1.8,
  });
  resources.push(jewelGeom, jewelMat);
  const jewelPivot = new THREE.Mesh(jewelGeom, jewelMat);
  jewelPivot.position.set(0, 0, 0);
  group.add(jewelPivot);

  // Arbor shafts
  const shaftGeom = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new THREE.MeshStandardMaterial({
    color: colorMap.ink,
    roughness: 0.5,
    metalness: 0.3,
  });
  resources.push(shaftGeom, shaftMat);

  const primaryShaft = new THREE.Mesh(shaftGeom, shaftMat);
  primaryShaft.position.set(0, 0, 0);
  group.add(primaryShaft);

  const secondaryShaft = new THREE.Mesh(shaftGeom, shaftMat);
  secondaryShaft.position.set(1.15, 0.35, -0.1);
  group.add(secondaryShaft);

  // Contact shadow
  const shadowGeom = new THREE.PlaneGeometry(2.6, 1.2);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
  });
  resources.push(shadowGeom, shadowMat);
  const shadowPlane = new THREE.Mesh(shadowGeom, shadowMat);
  shadowPlane.position.set(0, -1.2, 0.01);
  shadowPlane.rotation.x = -Math.PI / 2;
  group.add(shadowPlane);

  // Backdrop with radial gradient
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  resources.push(backdropGeom);

  const textureSize = 256;
  const textureData = new Uint8Array(textureSize * textureSize * 4);

  for (let i = 0; i < textureSize; i++) {
    for (let j = 0; j < textureSize; j++) {
      const x = (i - textureSize / 2) / (textureSize / 2);
      const y = (j - textureSize / 2) / (textureSize / 2);
      const dist = Math.min(Math.sqrt(x * x + y * y), 1.0);

      let r = 0, g = 0, b = 0;

      if (dist <= 0.65) {
        const t = dist / 0.65;
        r = Math.round(0x0b + (0x10 - 0x0b) * t);
        g = Math.round(0x0b + (0x10 - 0x0b) * t);
        b = Math.round(0x10 + (0x17 - 0x10) * t);
      } else {
        const t = (dist - 0.65) / 0.35;
        r = Math.round(0x10 + (0x16 - 0x10) * t);
        g = Math.round(0x10 + (0x16 - 0x10) * t);
        b = Math.round(0x17 + (0x1d - 0x17) * t);
      }

      const idx = (j * textureSize + i) * 4;
      textureData[idx] = r;
      textureData[idx + 1] = g;
      textureData[idx + 2] = b;
      textureData[idx + 3] = 255;
    }
  }

  const gradientTexture = new THREE.DataTexture(
    textureData,
    textureSize,
    textureSize,
    THREE.RGBAFormat
  );
  gradientTexture.needsUpdate = true;
  resources.push(gradientTexture);

  const backdropMat = new THREE.MeshBasicMaterial({ map: gradientTexture });
  resources.push(backdropMat);
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -3);
  group.add(backdrop);

  // Fog
  group.fog = new THREE.Fog(colorMap.background, 5, 11);

  // Text via fontAtlas
  if (ctx.fontAtlas) {
    try {
      const headlineText = ctx.fontAtlas.createMesh('The going train', {
        font: 'Lora',
        size: 0.68,
        weight: 600,
        color: colorMap.paper,
      });
      if (headlineText) {
        headlineText.position.set(0, -1.7, 0.1);
        group.add(headlineText);
      }

      const captionText = ctx.fontAtlas.createMesh('34 COMPONENTS / HAND-FINISHED', {
        font: 'JetBrains Mono',
        size: 0.18,
        weight: 400,
        color: colorMap.paper,
      });
      if (captionText) {
        captionText.position.set(0, -2.1, 0.1);
        group.add(captionText);
      }
    } catch (e) {
      console.warn('Text creation failed:', e);
    }
  }

  // Gear rotation animation: primary 0.08 rad/s, secondary -0.142 rad/s (16:9 ratio)
  const primaryAngularVelocity = 0.08;
  const secondaryAngularVelocity = 0.142;
  const rotationDuration = (Math.PI * 2) / primaryAngularVelocity;
  const gearRatio = secondaryAngularVelocity / primaryAngularVelocity;

  const rotationTl = gsap.timeline({ repeat: -1 });
  rotationTl.to(primaryGear.rotation, {
    z: Math.PI * 2,
    duration: rotationDuration,
    ease: 'none',
  }, 0);
  rotationTl.to(secondaryGear.rotation, {
    z: -(Math.PI * 2 * gearRatio),
    duration: rotationDuration,
    ease: 'none',
  }, 0);
  timelines.push(rotationTl);

  // Apply orbit primitive
  if (ctx.primitives && ctx.primitives.orbit) {
    ctx.primitives.orbit(group, {
      speed: 0.08,
      radius: 0.2,
    });
  }

  // Cleanup
  group.userData.cleanup = function() {
    timelines.forEach(tl => tl.kill());
    resources.forEach(res => {
      if (res.dispose) res.dispose();
    });
  };

  return group;
}
